    14→public static class ExecutionRequestExtensions
    15→{
    16→    public const int PublicKeySize = 48;
    17→    public const int WithdrawalCredentialsSize = Hash256.Size;
    18→    public const int AmountSize = sizeof(ulong);
    19→    public const int SignatureSize = 96;
    20→    public const int IndexSize = sizeof(ulong);
    21→    public const int DepositRequestsBytesSize = PublicKeySize + WithdrawalCredentialsSize + AmountSize + SignatureSize + IndexSize;
    22→
    23→    public const int WithdrawalRequestsBytesSize = Address.Size + PublicKeySize /*validator_pubkey: Bytes48*/ + sizeof(ulong) /*amount: uint64*/;
    24→    public const int ConsolidationRequestsBytesSize = Address.Size + PublicKeySize /*source_pubkey: Bytes48*/ + PublicKeySize /*target_pubkey: Bytes48*/;
    25→    public const int MaxRequestsCount = 3;
    26→
    27→
    28→
    29→    public static readonly byte[][] EmptyRequests = [];
    30→    public static readonly Hash256 EmptyRequestsHash = CalculateHashFromFlatEncodedRequests(EmptyRequests);
    31→
    32→    [SkipLocalsInit]
    33→    public static Hash256 CalculateHashFromFlatEncodedRequests(byte[][]? flatEncodedRequests)
    34→    {
    35→        // make sure that length is 3 or less elements
    36→        if (flatEncodedRequests is null)
    37→        {
    38→            throw new ArgumentException("Flat encoded requests must be an array");
    39→        }
    40→
    41→        using ArrayPoolList<byte> concatenatedHashes = new(Hash256.Size * MaxRequestsCount);
    42→        foreach (byte[] requests in flatEncodedRequests)
